+func (s *Service) HandleTextMessage(ctx context.Context, openID, content string) (MessageResult, error) {
+	openID = strings.TrimSpace(openID)
+	if openID == "" {
+		return MessageResult{}, repository.ErrInvalidInput
+	}
+	keywordValue := strings.TrimSpace(content)
+	adminRepo, configured := s.repo.(repository.WeChatAdminRepository)
+	if !configured {
+		if keywordValue != keyword {
+			return MessageResult{}, nil
+		}
+		code, err := s.IssueRegistrationCode(ctx, openID)
+		if err != nil {
+			return MessageResult{}, err
+		}
+		return MessageResult{Matched: true, Content: "你的专属注册码：" + code, Keyword: keyword, Action: domainwechat.ActionIssueRegistrationCode, Outcome: domainwechat.ResultIssued}, nil
+	}
+
+	rule, err := adminRepo.GetEnabledKeywordRule(ctx, keywordValue)
+	if err != nil {
+		if err == repository.ErrNotFound {
+			return MessageResult{}, nil
+		}
+		return MessageResult{}, err
+	}
+	result := MessageResult{Matched: true, Keyword: rule.Keyword, Action: rule.Action, TemplateID: rule.TemplateID}
+	if rule.Action != domainwechat.ActionIssueRegistrationCode {
+		return result, s.logFailure(ctx, adminRepo, openID, result, "unsupported_action", "unsupported WeChat action")
+	}
+	if !rule.TemplateEnabled || rule.TemplateType != domainwechat.ResponseTypeText || !strings.Contains(rule.TemplateContent, "{{CODE}}") {
+		return result, s.logFailure(ctx, adminRepo, openID, result, "invalid_template", "registration code template must be enabled text and contain {{CODE}}")
+	}
+
+	issue, err := s.issueDetailed(ctx, openID)
+	if err != nil {
+		result.Outcome = domainwechat.ResultFailed
+		_ = adminRepo.CreateInvocationLog(ctx, &domainwechat.InvocationLog{OpenID: openID, Keyword: result.Keyword, Action: result.Action, TemplateID: result.TemplateID, Result: domainwechat.ResultFailed, ErrorCode: "issue_failed", ErrorMessage: "registration code issuance failed"})
+		return result, err
+	}
+	result.RegistrationCodeID = issue.RegistrationCodeID
+	if issue.Created {
+		result.Outcome = domainwechat.ResultIssued
+	} else {
+		result.Outcome = domainwechat.ResultReplayed
+	}
+	result.Content = strings.ReplaceAll(rule.TemplateContent, "{{CODE}}", issue.Code)
+	_ = adminRepo.CreateInvocationLog(ctx, &domainwechat.InvocationLog{OpenID: openID, Keyword: result.Keyword, Action: result.Action, TemplateID: result.TemplateID, RegistrationCodeID: result.RegistrationCodeID, Result: result.Outcome})
